class DataClassJsonMixin:
    """
    DataClassJsonMixin is an abstract base class that serves as a mixin to provide functionality for converting dataclass instances into dictionaries, with optional support for JSON encoding of non-string values. This mixin should not be instantiated directly.

    The `to_dict` method provided by this mixin converts the instance of the dataclass it is mixed into into a dictionary representation. It supports nested structures within collections and mappings, applying custom overrides and JSON encoding as specified.

    Parameters:
        encode_json (bool): A flag indicating whether to apply JSON encoding to non-string values in the resulting dictionary. If True, all non-string values will be converted to their JSON representation before being included in the final output dictionary.

    Returns:
        dict: A dictionary representing the dataclass instance, with optional overrides and JSON encoding applied as specified.

    Examples:
        Basic usage with a dataclass instance:
            @dataclass
            class Point:
                x: int
                y: int

            point = Point(x=10, y=20)
            result = point.to_dict()  # Output: {'x': 10, 'y': 20}

        Using `encode_json` to apply JSON encoding:
            data = {'key': 'value'}
            encoded_data = DataClassJsonMixin().to_dict(encode_json=True)  # Output: {'key': '{"key": "value"}'}

        Handling nested structures within collections and mappings:
            @dataclass
            class NestedData:
                value1: int
                value2: List[Point]

            nested_data = NestedData(value1=30, value2=[Point(x=30, y=40)])
            nested_result = nested_data.to_dict()  # Output depends on the structure and values of `nested_data`
    """
    dataclass_json_config = None

    def to_dict(self, encode_json=False) -> Dict[str, Json]:
        return _asdict(self, encode_json=encode_json)
